# IPTVPremium: Capas 125, favoritos dos canais e ordem compartilhada. Base: java.zip enviado nesta conversa. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/PosterRowDownloader.kt'; Binary = $false; Allowed = @('A36C2811C74DCB8675C23D901108E3776A58F2BC8DC50280C1F89E5AC4A1139B'); MayCreate = $false; After = 'BADE1F383C0BC0C0FD5D340E30941D92EE210F7BA011530F6B9373277E3B9E16'; PayloadHash = 'BADE1F383C0BC0C0FD5D340E30941D92EE210F7BA011530F6B9373277E3B9E16'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/repository/PlaylistCatalogRepository.kt'; Binary = $false; Allowed = @('4E069325F77C1D8765733ADCF66055A3F3676DDAEB9D02934A791759B2FF0490'); MayCreate = $false; After = 'EBCD9111334DB35D547CEA14B26C4FB7443B3BCC739EC8805592CB7480CE5F95'; PayloadHash = 'EBCD9111334DB35D547CEA14B26C4FB7443B3BCC739EC8805592CB7480CE5F95'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/kids/KidsPolicy.kt'; Binary = $false; Allowed = @('52E5C80E723804ED78C13618EC8EC68B5B4A1EA6FF1016D3DC48F1871433AEE7'); MayCreate = $false; After = '7C36EC49851E082102E750BC6DB877753DA8CE12A7F35191F9A5B55B55856477'; PayloadHash = '7C36EC49851E082102E750BC6DB877753DA8CE12A7F35191F9A5B55B55856477'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/live/LiveTvScreen.kt'; Binary = $false; Allowed = @('AF29745B167A3DAB6FA7306014F853C1D000CD5A7A515F1F1EAE81BEE3459D4A'); MayCreate = $false; After = '0BF6F3CC014BF5E444D343A4B70613F65EB64CAAEFCDDDA28B71E0620E065B52'; PayloadHash = '0BF6F3CC014BF5E444D343A4B70613F65EB64CAAEFCDDDA28B71E0620E065B52'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/CategoryPosterPrefetch.kt'; Binary = $false; Allowed = @('5D08B6490974E5A641CB5B2C6D5E493E83EEE0FF4560C202B49B94332DBD6443'); MayCreate = $false; After = '0E669E4B46A58BBAF9AC63F7E76EE6CF2D85CB9431BBF0078449BCC67B72006A'; PayloadHash = '0E669E4B46A58BBAF9AC63F7E76EE6CF2D85CB9431BBF0078449BCC67B72006A'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MoviesScreen.kt'; Binary = $false; Allowed = @('89EF77DFFA5F17D2F60A6A603F06C02DD6E1C5D1EC5D4851B11DA44B460F689E'); MayCreate = $false; After = 'C50A9F110F23553F1E3713F798264F0B60AFB01FA85C3F07418F03ACCB9B5AAF'; PayloadHash = 'C50A9F110F23553F1E3713F798264F0B60AFB01FA85C3F07418F03ACCB9B5AAF'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/series/SeriesScreen.kt'; Binary = $false; Allowed = @('E919EDCF52391385FA9D0D2FB0C797BB8D61FC3004BE653F54265512808BADFA'); MayCreate = $false; After = 'E336C0F2A8F2B9F72B72EB02E0F745646FE4BB55B4C542DD8055C662841B44B7'; PayloadHash = 'E336C0F2A8F2B9F72B72EB02E0F745646FE4BB55B4C542DD8055C662841B44B7'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = if ($file.Binary) { Get-BytesHash $original } else { Get-TextHash $original }
        if ($current -eq $file.After) { continue }
        if ($file.Allowed -notcontains $current) {
            throw "Arquivo com mudancas diferentes da versao enviada: $($file.Path). Nada foi alterado; suas mudancas foram preservadas."
        }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $file.PayloadHash }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/catalogo-125-favoritos-ordem-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Atualizacao aplicada: janela de 125 capas; favoritos dos canais como filmes; ordem comum com cursos/adultos no final.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
